import type { EXECUTION_EFFECT_KINDS } from "../campus-model-core/execution-effects.contracts.js";

/**
 * This revision is deliberately manual. The repository verifier will not
 * rewrite a stale lock unless this number is increased first, so accepting
 * platform drift always leaves a reviewed Simulation change in the diff.
 */
export const SIMULATION_CONFORMANCE_REVISION = 232 as const;

export const SIMULATION_DATA_PLANE_CAPABILITIES = Object.freeze([
  "snapshot",
  "queries",
  "commands",
  "events",
  "realtime",
] as const);

export type SimulationDataPlaneCapability =
  (typeof SIMULATION_DATA_PLANE_CAPABILITIES)[number];

export type SimulationModuleDisposition =
  | "campus_operational"
  | "live_control_plane"
  | "provider_administration"
  | "simulation_control_plane";

export interface SimulationConformanceEvidence {
  readonly id: string;
  readonly kind: "real_postgres" | "http_journey" | "runtime_boundary";
  readonly test_file: string;
  readonly module_classes: readonly string[];
  readonly capabilities: readonly SimulationDataPlaneCapability[];
  /** A precise behavior asserted by the executable test, not a declaration of parity. */
  readonly proves: string;
}

export interface SimulationSafetyEvidence {
  readonly id: string;
  readonly kind: "unit_boundary" | "real_postgres" | "http_journey";
  readonly test_file: string;
  /** Exact fail-closed or isolated behavior exercised by the referenced test. */
  readonly proves: string;
}

export interface SimulationModuleRegistration {
  readonly module_class: string;
  readonly module_file: string;
  readonly source_roots: readonly string[];
  readonly disposition: SimulationModuleDisposition;
  readonly exclusion_reason?: string;
  /**
   * Evidence is capability-specific. Merely appearing in this registry never
   * makes a module ready; every required capability must have executable proof.
   */
  readonly evidence: readonly string[];
}

