export interface SimulationModuleCoverageResult {
  readonly ready: boolean;
  readonly incomplete: readonly string[];
  readonly covered_capabilities: Readonly<Record<string, readonly SimulationDataPlaneCapability[]>>;
}

/** Registration is not evidence: only capability-bearing executable proofs count. */
export function evaluateRegisteredModuleEvidence(): SimulationModuleCoverageResult {
  const evidence = new Map(SIMULATION_CONFORMANCE_EVIDENCE.map((item) => [item.id, item]));
  const incomplete: string[] = [];
  const covered: Record<string, readonly SimulationDataPlaneCapability[]> = {};
  for (const module of SIMULATION_MODULE_REGISTRY) {
    if (module.disposition !== "campus_operational") continue;
    const capabilities = new Set<SimulationDataPlaneCapability>();
    for (const evidenceId of module.evidence) {
      const proof = evidence.get(evidenceId);
      if (!proof) {
        incomplete.push(`${module.module_class}:unknown_evidence:${evidenceId}`);
        continue;
      }
      if (!new Set<string>(proof.module_classes).has(module.module_class)) {
        incomplete.push(`${module.module_class}:evidence_scope:${evidenceId}`);
        continue;
      }
      for (const capability of proof.capabilities) capabilities.add(capability);
    }
    covered[module.module_class] = Object.freeze(
      SIMULATION_DATA_PLANE_CAPABILITIES.filter((capability) => capabilities.has(capability)),
    );
    for (const capability of SIMULATION_DATA_PLANE_CAPABILITIES) {
      if (!capabilities.has(capability)) incomplete.push(`${module.module_class}:${capability}`);
    }
  }
  return Object.freeze({
    ready: incomplete.length === 0,
    incomplete: Object.freeze(incomplete.sort()),
    covered_capabilities: Object.freeze(covered),
  });
}
